using System;
using System.Drawing;
using System.Windows.Forms;
namespace ImageNdi {
public sealed class AudioMeterControl:Control {
 double lp=-120,rp=-120,lr=-120,rr=-120,holdL=-120,holdR=-120;DateTime holdUntil,clipUntil;string caption;
 public AudioMeterControl(){DoubleBuffered=true;ResizeRedraw=true;BackColor=Color.FromArgb(30,32,35);ForeColor=Color.White;Height=52;}
 public void SetLevels(string title,AudioLevels level){caption=title;lp=AudioLevels.Db(level.LeftPeak);rp=AudioLevels.Db(level.RightPeak);lr=AudioLevels.Db(level.LeftRms);rr=AudioLevels.Db(level.RightRms);if(DateTime.UtcNow>holdUntil){holdL=lp;holdR=rp;holdUntil=DateTime.UtcNow.AddSeconds(1);}else{holdL=Math.Max(holdL,lp);holdR=Math.Max(holdR,rp);}if(level.Clipped)clipUntil=DateTime.UtcNow.AddSeconds(2);Invalidate();}
 static int WidthFor(double db,int width){return (int)(Math.Max(0,Math.Min(1,(db+60)/60))*width);}
 protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(BackColor);int barWidth=Math.Max(1,Width-155);TextRenderer.DrawText(e.Graphics,caption??"Audio",Font,new Point(5,2),ForeColor);for(int channel=0;channel<2;channel++){int y=20+channel*14;double rms=channel==0?lr:rr,peak=channel==0?lp:rp,hold=channel==0?holdL:holdR;TextRenderer.DrawText(e.Graphics,channel==0?"L":"R",Font,new Point(5,y-2),ForeColor);e.Graphics.FillRectangle(Brushes.DimGray,25,y,barWidth,9);e.Graphics.FillRectangle(peak>=-3?Brushes.DarkOrange:Brushes.ForestGreen,25,y,WidthFor(rms,barWidth),9);e.Graphics.FillRectangle(Brushes.LightGreen,25+WidthFor(peak,barWidth),y,2,9);e.Graphics.DrawLine(Pens.White,25+WidthFor(hold,barWidth),y,25+WidthFor(hold,barWidth),y+9);TextRenderer.DrawText(e.Graphics,peak<=-100?"−∞ dBFS":peak.ToString("0.0")+" dBFS",Font,new Point(30+barWidth,y-2),ForeColor);}if(DateTime.UtcNow<clipUntil)TextRenderer.DrawText(e.Graphics,"CLIP",Font,new Point(Width-42,2),Color.OrangeRed);}
}
public partial class MainWindow {
 AudioManager audio;bool audioPending;readonly NumericUpDown audioGain=Number(-60,12,0);bool loadingAudioGain;
 readonly Label audioNotice=new Label{Name="AudioStatus",AutoSize=true,MaximumSize=new Size(800,32)};
 readonly CheckBox muteProgram=new CheckBox{Name="MuteProgramAudio",Text="Mute Program",AutoSize=true};readonly CheckBox mutePreview=new CheckBox{Name="MutePreviewAudio",Text="Mute Preview",AutoSize=true};
 readonly AudioMeterControl programAudioMeter=new AudioMeterControl{Name="ProgramAudioMeter",Dock=DockStyle.Bottom};readonly AudioMeterControl previewAudioMeter=new AudioMeterControl{Name="PreviewAudioMeter",Dock=DockStyle.Bottom};
 AudioBus ProgramAudio {get{return audio==null?null:audio.Program;}}AudioBus PreviewAudio {get{return audio==null?null:audio.Preview;}}
 double GainFor(string path){double value;return path!=null&&settings.AudioGains.TryGetValue(path,out value)?value:0;}
 void InitializeAudio(FlowLayoutPanel top,FlowLayoutPanel bottom){AddButton(top,"Uscite audio…",ShowAudioDialog);top.Controls.Add(audioNotice);audioGain.Name="VideoAudioGainDb";audioGain.DecimalPlaces=1;audioGain.Increment=.5m;var gainPanel=new FlowLayoutPanel{AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,WrapContents=false,Margin=new Padding(0)};AddField(gainPanel,"Gain video dB",audioGain);bottom.Controls.Add(gainPanel);bottom.Controls.Add(muteProgram);bottom.Controls.Add(mutePreview);
  ((Panel)program.Parent).Controls.Add(MonitorAudioStrip(programAudioMeter,programTransport));((Panel)preview.Parent).Controls.Add(MonitorAudioStrip(previewAudioMeter,previewTransport));
  files.SelectionChanged+=delegate{LoadAudioGain();};audioGain.ValueChanged+=delegate{if(loadingAudioGain||selected==null||!VideoTools.IsVideo(SourcePath(selected)))return;double db=(double)audioGain.Value;settings.AudioGains[selected]=db;if(audio!=null)audio.SetGain(selected,db);Save();};
  muteProgram.CheckedChanged+=delegate{settings.Audio.Program.Muted=muteProgram.Checked;if(ProgramAudio!=null)ProgramAudio.Muted=muteProgram.Checked;Save();};mutePreview.CheckedChanged+=delegate{settings.Audio.Preview.Muted=mutePreview.Checked;if(PreviewAudio!=null)PreviewAudio.Muted=mutePreview.Checked;Save();};
  bottom.Height=135;bottom.AutoScroll=true;ApplyAudioConfiguration();LoadAudioGain();
 }
 static Panel MonitorAudioStrip(AudioMeterControl meter,VideoTransportBar transport){var strip=new Panel{Name=meter.Name+"Strip",Dock=DockStyle.Bottom,Height=52,BackColor=Color.FromArgb(30,32,35)};meter.Dock=DockStyle.Fill;strip.Controls.Add(meter);strip.Controls.Add(transport);return strip;}
 void LoadAudioGain(){LoadVideoSpeed();loadingAudioGain=true;try{audioGain.Enabled=VideoTools.IsVideo(SourcePath(selected));audioGain.Value=(decimal)GainFor(selected);}finally{loadingAudioGain=false;}}
 void ApplyAudioConfiguration(){StopSelectionVideo();if(audio!=null)audio.Dispose();audio=new AudioManager(settings.Audio,AudioDevices.Open);audioPending=false;muteProgram.Checked=settings.Audio.Program.Muted;mutePreview.Checked=settings.Audio.Preview.Muted;}
 void AudioProjectChanged(){if(output!=null&&output.ReadOnAirStatus().Paths.Length>0){audioPending=true;LoadAudioGain();return;}ApplyAudioConfiguration();RenderPreview();LoadAudioGain();}
 void UpdateAudio(){if(audioPending&&(output==null||output.ReadOnAirStatus().Paths.Length==0)){ApplyAudioConfiguration();RenderPreview();}var pgm=ProgramAudio;var pv=PreviewAudio;programAudioMeter.SetLevels(pgm==null?"Audio Program · disabilitato":"Audio Program · "+pgm.Engine.Name,pgm==null?new AudioLevels():pgm.Meter.Take());previewAudioMeter.SetLevels(pv==null?"Audio Preview · disabilitato":"Audio Preview · "+pv.Engine.Name,pv==null?new AudioLevels():pv.Meter.Take());string error=audio==null?null:audio.ProgramError??audio.PreviewError??(pgm==null?null:pgm.Error)??(pv==null?null:pv.Error);audioNotice.Text=error!=null?"AUDIO: "+error:audioPending?"Uscite audio del progetto al prossimo clear Program":"Audio: "+(pgm!=null?"Program abilitato":"Program spento")+" · "+(pv!=null?"Preview abilitato":"Preview spento");audioNotice.ForeColor=error==null?Color.DimGray:Color.Firebrick;}
 void ShowAudioDialog(){if(output!=null&&output.ReadOnAirStatus().Paths.Length>0){MessageBox.Show("Per cambiare abilitazioni e schede audio pulisci prima Program. Gain e Mute restano regolabili durante la riproduzione.","Uscite audio");return;}using(var dialog=new Form{Text="Audio · Program e Preview",Width=820,Height=380,StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false}){var table=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=2,Padding=new Padding(8)};table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));table.RowStyles.Add(new RowStyle(SizeType.Percent,100));table.RowStyles.Add(new RowStyle(SizeType.Absolute,45));var devices=AudioDevices.Enumerate();Func<AudioRoute> readProgram,readPreview;table.Controls.Add(AudioRouteEditor("Program",settings.Audio.Program,devices,out readProgram),0,0);table.Controls.Add(AudioRouteEditor("Ascolto Preview",settings.Audio.Preview,devices,out readPreview),1,0);var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill};AddButton(buttons,"Applica",delegate{try{var config=new AudioConfiguration{Program=readProgram(),Preview=readPreview()};config.Validate();settings.Audio=config;ApplyAudioConfiguration();RenderPreview();Save();if(audio.ProgramError!=null||audio.PreviewError!=null){MessageBox.Show(audio.ProgramError??audio.PreviewError,"Uscita audio non disponibile");return;}dialog.DialogResult=DialogResult.OK;}catch(Exception e){MessageBox.Show(e.Message,"Audio");}});buttons.Controls.Add(new Button{Text="Annulla",AutoSize=true,DialogResult=DialogResult.Cancel});table.Controls.Add(buttons,0,1);table.SetColumnSpan(buttons,2);dialog.Controls.Add(table);dialog.ShowDialog(this);}}
 static Control AudioRouteEditor(string title,AudioRoute route,System.Collections.Generic.List<AudioDeviceInfo> devices,out Func<AudioRoute> read){var group=new GroupBox{Text=title,Dock=DockStyle.Fill};var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(8),AutoScroll=true};var enabled=new CheckBox{Text="Abilita lettura audio",AutoSize=true,Checked=route.Enabled};var list=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=345};foreach(var device in devices)list.Items.Add(device);for(int i=0;i<devices.Count;i++)if(devices[i].Backend==route.Backend&&devices[i].Id==route.DeviceId)list.SelectedIndex=i;var pair=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=140};for(int i=1;i<128;i+=2)pair.Items.Add(i+"–"+(i+1));pair.SelectedIndex=(route.FirstChannel-1)/2;var offset=Number(-500,500,route.VideoOffsetMs);panel.Controls.Add(enabled);panel.Controls.Add(new Label{Text="Scheda WDM/WASAPI o driver ASIO",AutoSize=true});panel.Controls.Add(list);panel.Controls.Add(new Label{Text="Coppia stereo di uscita",AutoSize=true});panel.Controls.Add(pair);panel.Controls.Add(new Label{Text="Correzione video ms (+ = ritarda il video)",AutoSize=true});panel.Controls.Add(offset);panel.Controls.Add(new Label{Text="ASIO: 48 kHz. Sulla stessa scheda scegli coppie diverse.\r\nSe manca una scheda, viene segnalato un errore.",AutoSize=true});group.Controls.Add(panel);read=delegate{var device=list.SelectedItem as AudioDeviceInfo;return new AudioRoute{Enabled=enabled.Checked,Muted=route.Muted,Backend=device==null?route.Backend:device.Backend,DeviceId=device==null?route.DeviceId:device.Id,FirstChannel=pair.SelectedIndex*2+1,VideoOffsetMs=(int)offset.Value};};return group;}
}
}
